<script setup>
import {ref,computed,onMounted,onUnmounted,watch} from 'vue';
import {locale,t,dateTime,number} from './i18n.js';
import labels,{errors} from './locales/reports.js';
const props=defineProps({api:Function,equipmentId:String});
const scope=ref('all'),period=ref('today'),language=ref(locale.value),rows=ref([]),config=ref(null),chosen=ref(null),selectedTab=ref('summary'),busy=ref(false),error=ref('');let timer,disposed=false,loading=false,epoch=0;
const running=computed(()=>rows.value.some(r=>['queued','collecting','analyzing','rendering'].includes(r.status)));
const report=computed(()=>chosen.value?.report),snapshot=computed(()=>report.value?.snapshot);
function rt(key){return labels[chosen.value?.language||locale.value]?.[key]||t(key)}
function failure(code){return errors[code]?.[['zh-TW','en','ja'].indexOf(locale.value)]||`${t('reportError')} (${code||'unknown'})`}
function format(value){return value==null?t('reportUnknown'):number(value,{maximumFractionDigits:2})}
function reportDate(value){if(!value)return '—';return new Intl.DateTimeFormat(chosen.value?.language||locale.value,{dateStyle:'short',timeStyle:'medium',timeZone:'Asia/Taipei'}).format(new Date(value))+' UTC+08:00'}
async function load(){if(disposed||document.hidden||loading)return;loading=true;const ticket=epoch;try{const list=await props.api('/reports');if(disposed||ticket!==epoch)return;rows.value=list;error.value='';if(chosen.value&&['queued','collecting','analyzing','rendering'].includes(chosen.value.status))await open(chosen.value.id);}catch(e){if(!disposed)error.value=e.message}finally{loading=false}}
async function open(id){const ticket=++epoch;try{const result=await props.api('/reports/'+id);if(disposed||ticket!==epoch)return;chosen.value=result;error.value='';}catch(e){if(!disposed&&ticket===epoch)error.value=e.message}}
async function generate(params){if(busy.value||running.value)return;busy.value=true;error.value='';try{const result=await props.api('/reports',{method:'POST',body:JSON.stringify({requestId:crypto.randomUUID(),equipmentId:params?.equipment||scope.value,period:params?.period||period.value,language:params?.language||language.value})});if(disposed)return;chosen.value=result;selectedTab.value='summary';rows.value=[result,...rows.value.filter(r=>r.id!==result.id)];await load()}catch(e){if(!disposed)error.value=e.message}finally{busy.value=false}}
function visible(){if(!document.hidden)load()}
onMounted(async()=>{try{config.value=await props.api('/reports/config')}catch(e){error.value=e.message}await load();if(!disposed){timer=setInterval(()=>{if(running.value)load()},5000);document.addEventListener('visibilitychange',visible)}});
onUnmounted(()=>{disposed=true;epoch++;clearInterval(timer);document.removeEventListener('visibilitychange',visible)});
watch(locale,()=>{if(!chosen.value)language.value=locale.value});
const tools=Array.from({length:10},(_,i)=>'TEL-CVDTIN-08A-'+String(i+1).padStart(2,'0'));
function chartTitle(dataset){return rt({timeline:'reportTimeline',states:'reportStates',production:'reportProduction',kla:'reportKla',vision:'reportVision',phm:'reportPhm'}[dataset])}
</script>
<template>
<div class="report-page">
<section class="panel report-builder"><div class="report-heading"><div><span class="eyebrow">AI · EXCEL</span><h2>{{t('reportTitle')}}</h2><p>{{t('reportHint')}}</p></div></div>
<form @submit.prevent="generate()" class="report-form"><label>{{t('reportScope')}}<select v-model="scope"><option value="all">{{t('reportAll')}}</option><option v-for="id in tools" :key="id" :value="id">{{id}}</option></select></label><label>{{t('reportPeriod')}}<select v-model="period"><option v-for="p in ['today','24h','7d','30d']" :key="p" :value="p">{{t({today:'reportToday','24h':'report24h','7d':'report7d','30d':'report30d'}[p])}}</option></select></label><label>{{t('reportLanguage')}}<select v-model="language"><option value="zh-TW">繁體中文</option><option value="en">English</option><option value="ja">日本語</option></select></label><button class="primary" :disabled="busy||running||config?.configured!==true">{{t('reportGenerate')}}</button></form>
<p class="report-disclosure">{{t('reportExternal')}}</p><p v-if="config&&!config.configured" class="report-warning" role="status">{{t('reportMissing')}}</p><p v-if="error" class="report-warning" role="alert">{{error}}</p>
</section>
<section class="panel report-history"><div class="report-heading"><h2>{{t('reportHistory')}}</h2><button @click="load" :disabled="loading">{{t('reportRefresh')}}</button></div><p v-if="!rows.length">{{t('reportEmpty')}}</p><div class="report-jobs"><article v-for="r in rows" :key="r.id" :class="['report-job',{selected:chosen?.id===r.id}]"><div><b>{{r.equipment==='all'?t('reportAll'):r.equipment}}</b><small>{{dateTime(r.created_at)}} · {{r.language}}</small></div><span :class="['report-status',r.status]" role="status">{{r.expired?t('reportExpired'):t(r.status)}}</span><button @click="open(r.id)">{{t('reportOpen')}}</button></article></div></section>
<section v-if="chosen" class="panel report-preview"><div class="report-heading"><div><h2>{{t('reportPreview')}}</h2><p>{{reportDate(chosen.cutoff)}} · {{chosen.language}}</p></div><a v-if="chosen.status==='completed'&&!chosen.expired" class="report-download" :href="'/api/reports/'+chosen.id+'/download'">{{t('reportDownload')}}</a></div><p>{{t('reportExpires')}} {{dateTime(chosen.expires_at)}}</p>
<p v-if="chosen.expired" class="report-warning">{{t('reportExpired')}}</p><div v-else-if="chosen.status==='failed'" class="report-warning" role="alert"><p>{{failure(chosen.error_code)}}</p><button :disabled="busy||running||!config?.configured" @click="generate(chosen)">{{t('reportRetry')}}</button></div><p v-else-if="chosen.status!=='completed'" class="report-stage" role="status">{{t(chosen.status)}}…</p>
<template v-if="report"><p class="report-disclosure">{{rt('reportNotice')}}</p><p class="report-disclosure">{{rt('reportBasis')}}</p><div class="report-tabs" role="tablist"><button v-for="section in ['summary','charts','data','quality']" :key="section" role="tab" :id="'report-tab-'+section" :aria-selected="selectedTab===section" :aria-controls="'report-panel-'+section" :class="{active:selectedTab===section}" @click="selectedTab=section">{{t('report'+section[0].toUpperCase()+section.slice(1))}}</button></div>
<div role="tabpanel" :id="'report-panel-'+selectedTab" :aria-labelledby="'report-tab-'+selectedTab">
<div v-if="selectedTab==='summary'" class="report-summary"><h3>{{rt('reportAi')}}</h3><article v-for="(section,i) in report.analysis.sections" :key="i"><h3>{{section.title}}</h3><p>{{section.text}}</p><details><summary>{{rt('reportSources')}}</summary><ul><li v-for="key in section.refs" :key="key">{{key}}: {{format(snapshot.metrics[key]?.value)}} {{snapshot.metrics[key]?.unit}}</li></ul></details></article></div>
<div v-else-if="selectedTab==='charts'" class="report-chart-grid"><p class="report-disclosure">{{rt('reportTrendSource')}}</p><figure v-for="chart in report.charts" :key="chart.dataset"><figcaption>{{chartTitle(chart.dataset)}}</figcaption><img :src="'/api/reports/'+chosen.id+'/charts/'+chart.dataset" :alt="chartTitle(chart.dataset)" loading="lazy"/></figure></div>
<div v-else-if="selectedTab==='data'" class="report-detail"><h3>{{rt('reportScope')}}</h3><div class="report-table-wrap"><table><thead><tr><th>{{rt('reportScope')}}</th><th>{{t('ui186')}}</th><th>{{t('ui187')}}</th><th>{{rt('reportCompleted')}}</th><th>{{rt('reportScrapped')}}</th><th>{{rt('reportDummy')}}</th></tr></thead><tbody><tr v-for="e in snapshot.equipment" :key="e.equipmentId"><td>{{e.equipmentId}}</td><td>{{format(e.utilization.utilization)}}</td><td>{{format(e.utilization.pmUtilization)}}</td><td>{{format(e.production.completed)}}</td><td>{{format(e.production.scrapped)}}</td><td>{{e.production.dummyCompleted}} / {{e.production.dummyScrapped}}</td></tr></tbody></table></div><p>{{rt('reportRows')}}</p>
<details><summary>{{rt('reportKla')}} · {{snapshot.klaTotal}} {{rt('reportCount')}}</summary><div class="report-table-wrap"><table><thead><tr><th>{{rt('reportWafer')}}</th><th>{{rt('reportRevision')}}</th><th>{{rt('reportThickness')}}</th><th>{{rt('reportUniformity')}}</th><th>{{rt('reportResult')}}</th></tr></thead><tbody><tr v-for="k in snapshot.kla" :key="k.id"><td>{{k.waferId}}</td><td>{{k.revision}}</td><td>{{format(k.meanNm)}}</td><td>{{format(k.uniformityPct)}}</td><td>{{k.thicknessQuality}}</td></tr></tbody></table></div></details>
<details><summary>{{rt('reportVision')}} · {{snapshot.visionTotal}} {{rt('reportCount')}}</summary><div class="report-table-wrap"><table><thead><tr><th>{{rt('reportWafer')}}</th><th>{{rt('reportRevision')}}</th><th>{{rt('reportDefects')}}</th><th>{{rt('reportResult')}}</th><th>Source</th></tr></thead><tbody><tr v-for="v in snapshot.vision" :key="v.id"><td>{{v.waferId}}</td><td>{{v.revision}} · {{v.kind}}</td><td>{{v.defectCount}}</td><td>{{v.quality}} · {{v.candidates?.join(', ')}}</td><td>{{v.mode}} · {{v.algorithmVersion}}</td></tr></tbody></table></div></details>
<details><summary>{{rt('reportPhm')}}</summary><p>{{rt('reportDenominator')}}</p><div class="report-table-wrap"><table><thead><tr><th>{{rt('reportScope')}}</th><th>LL</th><th>{{rt('reportHealth')}}</th><th>{{rt('reportRemaining')}}</th><th>{{rt('reportPassRate')}}</th><th>{{rt('reportPassed')}}</th></tr></thead><tbody><template v-for="e in snapshot.phm" :key="e.equipmentId"><tr v-for="p in e.pumps" :key="p.pumpId"><td>{{e.equipmentId}}</td><td>{{p.pumpId}}</td><td>{{format(p.lastHistorical?.health)}}</td><td>{{format(p.lastHistorical?.remainingCycles)}}</td><td>{{format(p.passRate)}}</td><td>{{p.counts.passed}} / {{p.counts.failed}} / {{p.counts.interrupted}}</td></tr></template></tbody></table></div></details></div>
<div v-else class="report-detail"><p v-if="snapshot.equipment.some(e=>e.coverage<100||e.production.quality!=='complete')">{{rt('reportPartial')}}</p><div class="report-table-wrap"><table><thead><tr><th>{{rt('reportScope')}}</th><th>{{rt('reportCoverage')}}</th><th>{{rt('reportProdCoverage')}}</th><th>{{rt('reportUnknownSeconds')}}</th><th>{{rt('reportPending')}}</th></tr></thead><tbody><tr v-for="e in snapshot.equipment" :key="e.equipmentId"><td>{{e.equipmentId}}</td><td>{{format(e.coverage)}}</td><td>{{format(e.production.coverage)}}</td><td>{{format(e.states.unknown)}}</td><td>{{snapshot.pending.find(p=>p.equipmentId===e.equipmentId)?.kla}} / {{snapshot.pending.find(p=>p.equipmentId===e.equipmentId)?.vision}}</td></tr></tbody></table></div><h3>{{rt('reportSources')}}</h3><p v-for="source in snapshot.sources" :key="source.source">{{source.source}} · {{reportDate(source.capturedAt)}}</p><p>{{report.analysis.model}} · {{report.analysis.promptVersion}}</p><p class="report-hash">SHA-256 {{report.snapshotHash}}</p></div>
</div></template></section></div>
</template>
<style scoped>
.report-page{display:grid;gap:24px;min-width:0}.report-page>.panel{min-width:0;max-width:100%}.report-builder h2{margin:8px 0}.report-heading{display:flex;justify-content:space-between;align-items:center;gap:18px}.report-heading h2{margin:0}.report-heading p{margin:8px 0}.report-form{display:grid;grid-template-columns:minmax(230px,2fr) minmax(150px,1fr) minmax(140px,1fr) auto;gap:18px;align-items:end;margin:24px 0}.report-form label{display:grid;gap:10px;font-weight:600}.report-form select{width:100%;min-width:0}.report-form button{min-height:48px;white-space:nowrap}.report-disclosure{color:var(--muted);line-height:1.7;margin:16px 0}.report-warning{background:var(--warning-surface,#fff5e8);border-left:3px solid #d89d3f;padding:16px;line-height:1.7;border-radius:8px;color:var(--fg)}.report-jobs{display:grid;gap:12px;margin-top:20px;max-height:450px;overflow:auto}.report-job{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:20px;align-items:center;border:1px solid var(--border);border-radius:12px;padding:16px}.report-job.selected{border-color:var(--accent);background:var(--surface-alt)}.report-job small{display:block;margin-top:8px;color:var(--muted)}.report-status{border-radius:30px;padding:7px 12px;background:var(--surface-alt);white-space:nowrap;color:var(--fg)}.report-status.failed{color:#d67354}.report-status.completed{color:#21977f}.report-download{display:inline-block;padding:12px 18px;background:var(--accent-strong);color:#fff;border-radius:8px;text-decoration:none;white-space:nowrap}.report-tabs{display:flex;gap:10px;margin:24px 0;flex-wrap:wrap;border-bottom:1px solid var(--border);padding-bottom:12px}.report-tabs button.active{background:var(--accent-strong);color:white;border-color:var(--accent-strong)}.report-summary{display:grid;gap:16px}.report-summary article{padding:20px;background:var(--surface-alt);border:1px solid var(--border);border-radius:12px}.report-summary h3{margin:0 0 12px}.report-summary p{line-height:1.85;white-space:pre-wrap}.report-summary details{margin-top:16px;color:var(--muted)}.report-chart-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.report-chart-grid>.report-disclosure{grid-column:1/-1}.report-chart-grid figure{margin:0;border:1px solid var(--border);border-radius:12px;padding:16px;background:var(--surface-alt)}.report-chart-grid figcaption{margin-bottom:12px;font-weight:600}.report-chart-grid img{width:100%;display:block;border-radius:6px}.report-table-wrap{max-width:100%;overflow-x:auto;margin:16px 0}.report-table-wrap table{min-width:720px;width:100%;font-size:14px}.report-table-wrap th,.report-table-wrap td{padding:14px;white-space:nowrap;border-bottom:1px solid var(--border);text-align:left}.report-detail details{padding:18px 0;border-top:1px solid var(--border)}.report-detail summary{cursor:pointer;font-weight:600}.report-hash{overflow-wrap:anywhere;font-size:13px;color:var(--muted)}.report-stage{padding:24px;background:var(--surface-alt);border-radius:12px}
@media(max-width:1100px){.report-form{grid-template-columns:repeat(2,minmax(0,1fr))}.report-chart-grid{grid-template-columns:1fr}}@media(max-width:600px){.report-form{grid-template-columns:1fr}.report-job{grid-template-columns:minmax(0,1fr) auto;gap:12px}.report-job>div{grid-column:1/-1}.report-heading{align-items:flex-start;flex-direction:column}.report-preview{padding:20px}.report-tabs button{flex:1;min-width:100px}.report-status{font-size:13px}}
</style>
